--
-- Table structure for table `inventario_repuesto`
--

DROP TABLE IF EXISTS `inventario_repuesto`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `inventario_repuesto` (
  `id_repuesto` bigint unsigned NOT NULL AUTO_INCREMENT,
  `codigo_repuesto` varchar(30) NOT NULL,
  `descripcion` varchar(150) NOT NULL,
  `cantidad_disponible` int unsigned NOT NULL DEFAULT '0',
  `cantidad_minima` int unsigned NOT NULL DEFAULT '1',
  `costo_unitario` decimal(10,2) NOT NULL,
  `id_aeropuerto_bodega` int unsigned NOT NULL,
  PRIMARY KEY (`id_repuesto`),
  UNIQUE KEY `codigo_repuesto` (`codigo_repuesto`),
  KEY `fk_inventario_aeropuerto` (`id_aeropuerto_bodega`),
  FULLTEXT KEY `ft_repuesto_descripcion` (`descripcion`),
  CONSTRAINT `fk_inventario_aeropuerto` FOREIGN KEY (`id_aeropuerto_bodega`) REFERENCES `aeropuerto` (`id_aeropuerto`),
  CONSTRAINT `ck_inventario_costo` CHECK ((`costo_unitario` >= 0))
) ENGINE=InnoDB AUTO_INCREMENT=301 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

